//
// Pins the customizeUI color mapping of upstream #902: the three integer
// keys ride the same UI object as candFontName, a configured 24-bit value is
// honored, and anything absent or malformed falls back to the caller's
// sentinel (0 = follow the system palette).

#include "UIColors.h"

#include <iostream>
#include <nlohmann/json.hpp>

namespace {

int failures = 0;

void expect(bool ok, const char* what) {
	if (!ok) {
		std::cerr << "FAIL  " << what << '\n';
		++failures;
	}
}

} // namespace

int main() {
	using json = nlohmann::json;

	const json ui = json::parse(
		"{\"candFontName\": \"MingLiu\", \"candFontSize\": 12,"
		" \"candTextColor\": 1193046,"
		" \"windowBackgroundColor\": 16777215,"
		" \"selKeyColor\": 255}");

	expect(PIME::uiColorValue(ui, "candTextColor", 0) == 0x123456u,
		"a configured candidate text color is honored");
	expect(PIME::uiColorValue(ui, "windowBackgroundColor", 0) == 0xFFFFFFu,
		"a configured window background is honored");
	expect(PIME::uiColorValue(ui, "selKeyColor", 0) == 0x0000FFu,
		"a configured selection-key color is honored");

	// absent values fall back
	const json bare = json::parse("{\"candFontName\": \"MingLiu\"}");
	expect(PIME::uiColorValue(bare, "candTextColor", 7) == 7u,
		"an absent color falls back to the caller's sentinel");
	expect(PIME::uiColorValue(bare, "selKeyColor", 7) == 7u,
		"an absent selection-key color falls back too");

	// malformed values also fall back
	const json bad = json::parse(
		"{\"candTextColor\": \"123456\","
		" \"windowBackgroundColor\": 16777216,"
		" \"selKeyColor\": -1}");
	expect(PIME::uiColorValue(bad, "candTextColor", 3) == 3u,
		"a string value is not a color");
	expect(PIME::uiColorValue(bad, "windowBackgroundColor", 3) == 3u,
		"past the 24-bit range falls back");
	expect(PIME::uiColorValue(bad, "selKeyColor", 3) == 3u,
		"a negative value falls back");

	// a non-object reply falls back wholesale
	const json scalar = json::parse("42");
	expect(PIME::uiColorValue(scalar, "candTextColor", 9) == 9u,
		"a non-object UI value falls back");

	if (failures == 0) {
		std::cout << "ui colors: all assertions passed\n";
		return 0;
	}
	std::cerr << failures << " assertion(s) failed\n";
	return 1;
}
